mapper.select:
SELECT u.id AS user_id, u.display_name AS label FROM sys_user u JOIN sys_dept d ON d.id = u.dept_id
WHERE u.enabled AND d.enabled AND NOT u.must_change_password AND 
AND u.display_name ILIKE #{like} ESCAPE E'\\'
AND u.id > #{afterId}
ORDER BY u.id ASC LIMIT #{fetch}

SELECT u.id AS user_id, u.enabled, COALESCE(d.enabled, FALSE) AS department_enabled,
    u.must_change_password AS password_change_required,  AS handle_permission
FROM sys_user u LEFT JOIN sys_dept d ON d.id = u.dept_id WHERE u.id = #{userId}
